function plainThree(base,l){
 const n=native(l); if(!n||!base?.positions?.length)return base;
 const x=base.positions.map(z=>p(z.cardId,n)); if(x.some(v=>!v))return base;
 const pos=base.positions.map((z,i)=>Object.freeze({...z,text:n==='th'
  ?(i===0?`ที่ผ่านมา: ${x[i].meaning}`:i===1?`ตอนนี้: ${x[i].meaning} ทำต่อแบบนี้: ${x[i].action}`:`ต่อไป: ${x[i].meaning}`)
  :(i===0?`What led here: ${x[i].meaning}`:i===1?`Right now: ${x[i].meaning} What to do next: ${x[i].action}`:`What may come next: ${x[i].meaning}`)
 }));
 return Object.freeze({...base,positions:Object.freeze(pos),
  story:n==='th'?'สรุปง่ายๆ: ไพ่ใบแรกบอกสิ่งที่พามาถึงตรงนี้ ไพ่ใบกลางคือเรื่องที่ต้องจัดการตอนนี้ และสิ่งที่คุณทำตรงนี้มีผลกับทางต่อไปมากที่สุด':'Simple summary: The first card shows what led here. The middle card is what matters now, and what you do here has the biggest effect on what comes next.',
  turningPoint:n==='th'?`สิ่งสำคัญที่สุดตอนนี้: ${x[1].action}`:`Most important now: ${x[1].action}`,
  pattern:n==='th'?'ลำดับของเรื่องคือ เข้าใจสิ่งที่พามาถึงตรงนี้ จัดการปัจจุบัน แล้วค่อยดูทางต่อไป':'The order is simple: understand what led here, deal with the present, then move toward the next direction.',
  guidance:n==='th'?`ทำต่อแบบนี้: ${x[1].action} หลังจากนั้น: ${x[2].action}`:`Do this next: ${x[1].action} After that: ${x[2].action}`,
  reflection:n==='th'?'ถามตัวเอง: ตอนนี้ฉันทำอะไรได้หนึ่งอย่างเพื่อให้เรื่องนี้ดีขึ้น?':'Ask yourself: What is one thing I can do now to improve this situation?'
 });
}
